import java.util.*;

class Solution {
  private List<int[]>[] graph;
  private int[] answer;

  public int[] minEdgeReversals(int n, int[][] edges) {
    graph = new ArrayList[n];
    for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
    for (int[] e : edges) {
      graph[e[0]].add(new int[] {e[1], 0});
      graph[e[1]].add(new int[] {e[0], 1});
    }
    answer = new int[n];
    answer[0] = first(0, -1);
    reroot(0, -1);
    return answer;
  }

  private int first(int u, int parent) {
    int total = 0;
    for (int[] e : graph[u]) if (e[0] != parent) total += e[1] + first(e[0], u);
    return total;
  }

  private void reroot(int u, int parent) {
    for (int[] e : graph[u])
      if (e[0] != parent) {
        answer[e[0]] = answer[u] + (e[1] == 0 ? 1 : -1);
        reroot(e[0], u);
      }
  }
}
